class VLParser_Vframe:
    # Vframe is the frame for enter and exit.
    # this emulates the function style qwq.
    vframes = list()
    _current_vframe = 'main'
    _in_vframe = False
    def goto_vframe(key):
        value = VLParser_Vframe.vframes.get(VLParser_Vframe._current_vframe)
        if(value):
            VLParser_Vframe.vframes[VLParser_Vframe._current_vframe] = value - 1
            if(VLParser_Vframe.vframes[VLParser_Vframe._current_vframe] == 0):
                VLParser_Vframe.vframes.pop(VLParser_Vframe._current_vframe)
        VLParser_Vframe._current_vframe = key
        VLParser_Vframe._in_vframe = True
        value = VLParser_Vframe.vframes.get(VLParser_Vframe._current_vframe)
        if(value == None):
            VLParser_Vframe.vframes[VLParser_Vframe._current_vframe] = 1
        else:
            VLParser_Vframe.vframes[VLParser_Vframe._current_vframe] += 1
        return


    def enter_vframe(key):
        if(VLParser_Vframe._in_vframe):
            # Yet we can recursive enter <current_vframe>, as it's the same scope.
            if(VLParser_Vframe._current_vframe != key):
                VLParser_Vframe.goto_vframe(key)
            return
        VLParser_Vframe.goto_vframe(key)


    def exit_vframe(key):
        assert(\
            (VLParser_Vframe._in_vframe and VLParser_Vframe._current_vframe == key) or\
            (not VLParser_Vframe._in_vframe and 'main' == key),\
            'Unexpected call from the vframe currently:' + str(VLParser_Vframe._current_vframe))
        VLParser_Vframe.goto_vframe('main')
        value = VLParser_Vframe.vframes.get('main')
        if(value == None):
            VLParser_Vframe.vframes['main'] = 1
        else:
            VLParser_Vframe.vframes['main'] += 1

class VLParser_State:
    def __init__(self):
        self.variables = {'main': {}}
        self.last_var = None
        self.declare_var_push = False
        self.function_state = {}

    def push(self, key, token):
        self.variables[VLParser_Vframe._current_vframe][key] = token
        self.last_var = [key, token]

    def get(self, key):
        t = VLParser_Vframe._current_vframe
        if (t in self.variables):
            value = self.variables[t][key]
            if (isinstance(value, list)):
                if(key in value): # key == value[0]
                    return value[1]
                else:
                    return False
            else:
                return value
        return False

    def isdefine(self,key):
        return self.get(key) != False
    def declare_var(self,key):
        self.declare_var_push = False
        #assert(not self.isdefine(key),' duplicate variable name: ' + str(key))
        if (not self.isdefine(key)):
            self.push(key, 'ref')
            self.last_var = [key, 'ref']
            self.declare_var_push = True

    def identify_var(self,key):
        t = VLParser_Vframe._current_vframe
        if (t in self.variables):
            if(key in self.variables[t]):
                return True
    def assert_var(self,key):
        if(self.identify_var(key)):
            self.last_var = [key, self.variables[VLParser_Vframe._current_vframe][key]]
        else:
            assert(False,'variable %r is not defined yet')%(key,)
    def pop_last_var(self):
        current_vframe = VLParser_Vframe._current_vframe
        last_var = self.last_var
        if(self.declare_var_push):
            self.variables[current_vframe].pop(last_var[0])
        elif(last_var):
            self.variables[current_vframe][last_var[0]] = 'nil'
        else:
            assert(\
                self.variables[current_vframe].get(last_var[0]) == 'nil', \
                'variable not identify')
        self.last_var = last_var
        self
